const LIMITE_POR_HORA = 10;
const req = $('Novo carrossel (POST)').first().json;
const b = (req.body && typeof req.body === 'object') ? req.body : {};
const usos = Number(Object.values($input.first().json)[0]) || 0;
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const ESTILOS = ['escuro', 'claro', 'vibrante', 'natural', 'corporativo'];
const d = {
  tema: limpa(b.tema, 160), perfil: limpa(b.perfil, 30).replace(/^@+/, '').replace(/[^\w.]/g, ''),
  publico: limpa(b.publico, 200), objetivo: limpa(b.objetivo, 60) || 'ensinar', tom: limpa(b.tom, 60) || 'direto e próximo',
  estilo: ESTILOS.includes(b.estilo) ? b.estilo : 'escuro', cta: limpa(b.cta, 120) || 'Salve este post e siga para mais dicas',
  palavra: limpa(b.palavra, 20).replace(/[^\p{L}\p{N}]/gu, ''),
};
const erros = [];
if (d.tema.length < 5) erros.push('Descreva o tema do carrossel.');
if (d.perfil.length < 2) erros.push('Informe o @ do perfil.');
if (String(b.site || '').trim()) erros.push('Requisição recusada.');
if (usos > LIMITE_POR_HORA) erros.unshift('Muitos carrosséis criados nesta rede na última hora. Tente mais tarde.');
const rnd = n => Array.from({ length: n }, () => 'abcdefghijkmnpqrstuvwxyz23456789'[Math.floor(Math.random() * 32)]).join('');
const id = 'car-' + Date.now().toString(36) + rnd(4);
const k = rnd(18);
const base = String(req.webhookUrl || '').split('/webhook/')[0] || 'https://webhookn8n6.inovareinteligenciaartificial.com';
return [{ json: { valido: erros.length === 0, erros, codigo_http: usos > LIMITE_POR_HORA ? 429 : 400, id, k, base, dados: d,
  link: `${base}/webhook/insta-carrossel-ver?id=${id}&k=${k}`, criadoEm: new Date().toISOString() } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

const r = $('Validar pedido do carrossel').first().json;
const ia = parseJSON($input.first().json.output ?? '') || {};
const FONTES = '/usr/share/fonts/truetype/msttcorefonts/';
const PALETAS = {
  escuro: { fundo: '#0f172a', destaque: '#f59e0b', titulo: '#ffffff', texto: '#cbd5e1', rodape: '#94a3b8', tit: 'Verdana_Bold.ttf', txt: 'Verdana.ttf' },
  claro: { fundo: '#fafaf9', destaque: '#e11d48', titulo: '#111827', texto: '#374151', rodape: '#6b7280', tit: 'Verdana_Bold.ttf', txt: 'Verdana.ttf' },
  vibrante: { fundo: '#5b21b6', destaque: '#facc15', titulo: '#ffffff', texto: '#ede9fe', rodape: '#ddd6fe', tit: 'Verdana_Bold.ttf', txt: 'Verdana.ttf' },
  natural: { fundo: '#f1f5ec', destaque: '#2f855a', titulo: '#1c3324', texto: '#3f5a47', rodape: '#6b8573', tit: 'Georgia_Bold.ttf', txt: 'Georgia.ttf' },
  corporativo: { fundo: '#0b3a6e', destaque: '#38bdf8', titulo: '#ffffff', texto: '#dbeafe', rodape: '#93c5fd', tit: 'Verdana_Bold.ttf', txt: 'Verdana.ttf' },
};
const P = PALETAS[r.dados.estilo] || PALETAS.escuro;

// Sem emoji (as fontes do servidor não têm) e sem aspas retas (quebram o comando de desenho)
const limpa = (s, max) => String(s ?? '').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, '')
  .replace(/"/g, '”').replace(/'/g, '’').replace(/\\/g, '/').replace(/\s+/g, ' ').trim().slice(0, max);
function quebra(texto, porLinha) {
  const linhas = []; let atual = '';
  for (const p of texto.split(' ')) {
    if ((atual + ' ' + p).trim().length > porLinha && atual) { linhas.push(atual); atual = p; } else atual = (atual + ' ' + p).trim();
  }
  if (atual) linhas.push(atual);
  return linhas;
}

const d = r.dados;
const capa = ia.capa || {}, cta = ia.cta || {};
let meio = Array.isArray(ia.slides) ? ia.slides.slice(0, 4) : [];
while (meio.length < 4) meio.push({ titulo: d.tema, texto: 'Salve este post para consultar depois.' });
const roteiro = [
  { tipo: 'capa', titulo: limpa(capa.titulo || d.tema, 70), texto: limpa(capa.subtitulo, 110) },
  ...meio.map(s => ({ tipo: 'conteudo', titulo: limpa(s.titulo, 60), texto: limpa(s.texto, 280) })),
  { tipo: 'cta', titulo: limpa(cta.titulo || 'Gostou? Salve e compartilhe!', 60), texto: limpa(cta.texto || d.cta, 170) },
];

const W = 1080, H = 1350, X = 90;
const slides = roteiro.map((s, i) => {
  const capaOuCta = s.tipo !== 'conteudo';
  const tTam = s.tipo === 'capa' ? 84 : capaOuCta ? 72 : 66;
  const tLinhas = quebra(s.titulo, s.tipo === 'capa' ? 16 : 20);
  const xTam = capaOuCta ? 46 : 44;
  const xLinhas = quebra(s.texto, capaOuCta ? 33 : 35).slice(0, 10);
  // Centraliza o bloco (título + texto) na área entre o cabeçalho e o rodapé
  const tLH = Math.round(tTam * 1.22), xLH = Math.round(xTam * 1.24);
  const altura = tLinhas.length * tLH + (xLinhas.length ? 60 + xLinhas.length * xLH : 0);
  const topo = 210 + Math.max(0, Math.round((950 - altura) / 2));
  const tY = Math.round(topo + tTam * 0.85);
  const xY = Math.round(topo + tLinhas.length * tLH + 60 + xTam * 0.85);
  return { json: { n: i + 1, tipo: s.tipo, titulo: tLinhas.join('\n'), texto: xLinhas.join('\n'),
    tTam, xTam, tY, xY, W, H, X, cor: P, fonteTitulo: FONTES + P.tit, fonteTexto: FONTES + P.txt,
    contador: `${i + 1}/6`, rodape: '@' + d.perfil, seta: i < 5 ? 'arraste  »' : (d.palavra ? `comente ${d.palavra.toUpperCase()}` : 'salve e compartilhe') } };
});

const tags = (Array.isArray(ia.hashtags) ? ia.hashtags : []).map(t => '#' + String(t).replace(/[^\p{L}\p{N}_]/gu, '')).filter(t => t.length > 2).slice(0, 8);
let legenda = String(ia.legenda || '').trim().slice(0, 1800);
if (d.palavra && !legenda.toUpperCase().includes(d.palavra.toUpperCase())) legenda += `\n\n💬 Comente ${d.palavra.toUpperCase()} que eu te mando o link no direct!`;
if (tags.length) legenda += '\n\n' + tags.join(' ');
// Alerta se o texto veio sem acentos (o modelo às vezes esquece)
const tudo = roteiro.map(s => s.titulo + ' ' + s.texto).join(' ') + ' ' + legenda;
const semAcento = (tudo.match(/\b(voce|voces|nao|sao|tambem|negocio|negocios|horario|horarios|ate|facil|rapido|automacao|automacoes|inteligencia|conteudo|proximo|unico|ultimo|ja|sera|e possivel)\b/gi) || []).length;
const alerta = semAcento >= 2 ? `O texto parece estar sem acentos (${semAcento} palavras como "voce" ou "nao"). Revise antes de publicar ou crie de novo.` : '';
return slides.map(s => ({ json: { ...s.json, legenda, alerta, roteiro_ok: !!(ia.capa && ia.slides) } }));

// O Edit Image entrega a imagem como arquivo; aqui viramos texto (base64) para guardar no Redis
const itens = $input.all();
const saida = [];
for (let i = 0; i < itens.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  saida.push({ json: { n: itens[i].json.n, b64: buf.toString('base64'), kb: Math.round(buf.length / 1024) } });
}
return saida;

const v = $('Validar pedido do carrossel').first().json;
const slides = $('Organiza slides').all().map(i => i.json);
const imagens = $('Imagem para base64').all().map(i => i.json);
const urls = slides.map(s => `${v.base}/webhook/insta-img?id=${v.id}&n=${s.n}`);
const rascunho = {
  id: v.id, k: v.k, status: 'aguardando', dados: v.dados, legenda: slides[0].legenda,
  slides: slides.map(s => ({ n: s.n, tipo: s.tipo, titulo: s.titulo.replace(/\n/g, ' '), texto: s.texto.replace(/\n/g, ' ') })),
  urls, kb: imagens.map(i => i.kb), roteiro_ia: slides[0].roteiro_ok, alerta: slides[0].alerta || '',
  criadoEm: v.criadoEm, atualizadoEm: new Date().toISOString(),
};
return [{ json: { rascunho_str: JSON.stringify(rascunho) } }];

const b64 = $input.first().json.img;
if (!b64) return [{ json: { achou: false } }];
return [{ json: { achou: true }, binary: { data: { data: b64, mimeType: 'image/jpeg', fileName: 'slide.jpg', fileExtension: 'jpg' } } }];

const q = $('Ver carrossel (GET)').first().json.query || {};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
let r = null;
try { r = JSON.parse($input.first().json.rascunho || 'null'); } catch (e) {}
const casca = (titulo, corpo, refresh) => `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">${refresh ? '<meta http-equiv="refresh" content="5">' : ''}<title>${esc(titulo)}</title>
<style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:#fafafa;color:#262626;padding:20px 14px 60px}
.w{max-width:560px;margin:0 auto}.cab{display:flex;align-items:center;gap:10px;margin-bottom:12px}.av{width:38px;height:38px;border-radius:50%;background:linear-gradient(45deg,#f58529,#dd2a7b,#8134af);padding:2px}.av i{display:block;width:100%;height:100%;border-radius:50%;background:#fff}
.post{background:#fff;border:1px solid #dbdbdb;border-radius:12px;overflow:hidden}.trilho{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none}.trilho::-webkit-scrollbar{display:none}
.trilho img{width:100%;flex:none;scroll-snap-align:start;aspect-ratio:4/5;object-fit:cover;background:#eee}.pts{display:flex;justify-content:center;gap:5px;padding:10px}.pts b{width:6px;height:6px;border-radius:50%;background:#c7c7c7}
.leg{padding:4px 14px 14px;font-size:14px;white-space:pre-wrap}.box{background:#fff;border:1px solid #dbdbdb;border-radius:12px;padding:16px;margin-top:14px}
label{display:block;font-weight:600;font-size:13px;margin:10px 0 6px}textarea,input{width:100%;padding:11px;border:1px solid #dbdbdb;border-radius:10px;font:inherit;font-size:14px}textarea{min-height:170px}
.bts{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.bt{flex:1 1 150px;border:0;border-radius:10px;padding:13px;font:inherit;font-weight:700;cursor:pointer;background:#efefef;color:#262626}
.bt.pub{background:#0095f6;color:#fff}.bt:disabled{opacity:.55;cursor:wait}.msg{margin-top:12px;font-weight:600;font-size:14px}.ok{color:#2e9e5b}.er{color:#d03b3b}
.tag{display:inline-block;padding:3px 10px;border-radius:999px;font-size:12.5px;font-weight:700;background:#efefef}.s{width:44px;height:44px;border:4px solid #efefef;border-top-color:#dd2a7b;border-radius:50%;margin:60px auto 16px;animation:r .8s linear infinite}@keyframes r{to{transform:rotate(360deg)}}h1{font-size:20px}.mu{color:#8e8e8e;font-size:13px}</style></head><body><div class="w">${corpo}</div></body></html>`;

if (!r || q.k !== r.k) return [{ json: { codigo: 404, html: casca('Não encontrado', '<h1 style="text-align:center;margin-top:60px">Carrossel não encontrado</h1><p class="mu" style="text-align:center">Confira o link completo, com a chave.</p>') } }];
if (r.status === 'gerando') return [{ json: { codigo: 200, html: casca('Criando o carrossel…', '<div class="s"></div><h1 style="text-align:center">A IA está escrevendo e desenhando os 6 slides</h1><p class="mu" style="text-align:center">Esta página se atualiza sozinha. Leva de 1 a 3 minutos.</p>', true) } }];
if (r.status === 'erro_geracao') return [{ json: { codigo: 500, html: casca('Erro', `<h1>Não foi possível criar o carrossel</h1><p class="mu">${esc(r.erro)}</p>`) } }];

const STATUS = { aguardando: '📝 Aguardando aprovação', agendado: '⏰ Agendado', publicado: '✅ Publicado', erro: '⚠️ Falhou ao publicar', descartado: '🗑️ Descartado' };
const quando = r.quando ? new Date(r.quando).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '';
const imgs = r.urls.map((u, i) => `<img src="${esc(u)}" alt="Slide ${i + 1}" loading="${i ? 'lazy' : 'eager'}">`).join('');
const pode = ['aguardando', 'erro', 'agendado'].includes(r.status);
const corpo = `<div class="cab"><span class="av"><i></i></span><div><b>${esc(r.dados.perfil)}</b><div class="mu">${esc(r.dados.tema)}</div></div></div>
<p style="margin-bottom:10px"><span class="tag">${STATUS[r.status] || esc(r.status)}</span>${quando ? ` <span class="mu">para ${esc(quando)}</span>` : ''}${r.permalink ? ` · <a href="${esc(r.permalink)}" target="_blank" rel="noopener">ver no Instagram</a>` : ''}</p>
${r.erro && r.status === 'erro' ? `<p class="msg er">${esc(r.erro)}</p>` : ''}
${r.alerta && pode ? `<p class="msg er">⚠️ ${esc(r.alerta)}</p>` : ''}
<div class="post"><div class="trilho" id="tr">${imgs}</div><div class="pts">${r.urls.map(() => '<b></b>').join('')}</div><div class="leg" id="legPrev">${esc(r.legenda)}</div></div>
${pode ? `<div class="box"><label for="leg">Legenda (pode editar)</label><textarea id="leg" maxlength="2200">${esc(r.legenda)}</textarea>
<label for="senha">Senha de publicação</label><input id="senha" type="password" placeholder="Só quem tem a senha publica na conta" autocomplete="off">
<label for="quando">Agendar para (opcional)</label><input id="quando" type="datetime-local">
<div class="bts"><button class="bt pub" data-a="publicar" type="button">🚀 Publicar agora</button><button class="bt" data-a="agendar" type="button">⏰ Agendar</button>
${r.status === 'agendado' ? '<button class="bt" data-a="cancelar" type="button">✖ Cancelar agendamento</button>' : '<button class="bt" data-a="descartar" type="button">🗑️ Descartar</button>'}</div><p class="msg" id="msg" role="status"></p></div>` : ''}
<p class="mu" style="margin-top:14px">Dica: os slides são imagens 1080×1350 (formato 4:5, o que mais aparece no feed).</p>
<script>
var tr=document.getElementById('tr'),pts=document.querySelectorAll('.pts b');function marca(){var i=Math.round(tr.scrollLeft/tr.clientWidth);pts.forEach(function(p,j){p.style.background=j===i?'#0095f6':'#c7c7c7';});}tr.addEventListener('scroll',marca);marca();
document.querySelectorAll('[data-a]').forEach(function(b){b.addEventListener('click',function(){
  var a=b.getAttribute('data-a'),m=document.getElementById('msg'),q=document.getElementById('quando');
  if(a==='agendar'&&!q.value){m.className='msg er';m.textContent='Escolha a data e a hora do agendamento.';return;}
  if(a==='publicar'&&!confirm('Publicar agora na conta do Instagram?'))return;
  document.querySelectorAll('[data-a]').forEach(function(x){x.disabled=true;});m.className='msg';m.textContent=a==='publicar'?'Publicando… pode levar até 1 minuto.':'Salvando…';
  fetch('/webhook/insta-carrossel-acao',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:${JSON.stringify(r.id)},k:${JSON.stringify(r.k)},acao:a,senha:document.getElementById('senha').value,legenda:document.getElementById('leg').value,quando:q.value})})
   .then(function(x){return x.json();}).then(function(j){if(!j.ok){m.className='msg er';m.textContent=j.erro||'Não foi possível.';document.querySelectorAll('[data-a]').forEach(function(x){x.disabled=false;});return;}m.className='msg ok';m.textContent=j.mensagem||'Feito!';setTimeout(function(){location.reload();},1500);})
   .catch(function(){m.className='msg er';m.textContent='Falha de conexão.';document.querySelectorAll('[data-a]').forEach(function(x){x.disabled=false;});});
});});
</script>`;
return [{ json: { codigo: 200, html: casca('Aprovar carrossel', corpo) } }];

// 🔐 Senha para publicar ou agendar na conta do Instagram (troque aqui)
const SENHA = '<SEGREDO_REMOVIDO>';
const b = $('Ação no carrossel (POST)').first().json.body || {};
let r = null;
try { r = JSON.parse($input.first().json.rascunho || 'null'); } catch (e) {}
const nao = (erro, codigo = 400) => [{ json: { ok: false, erro, codigo } }];
if (!r || b.k !== r.k) return nao('Carrossel não encontrado.', 404);
const acao = String(b.acao || '');
if (!['publicar', 'agendar', 'descartar', 'cancelar'].includes(acao)) return nao('Ação inválida.');
if ((acao === 'publicar' || acao === 'agendar') && b.senha !== SENHA) return nao('Senha de publicação incorreta.', 403);
if (r.status === 'publicado') return nao('Este carrossel já foi publicado.');
if (acao === 'cancelar' && r.status !== 'agendado') return nao('Não há agendamento para cancelar.');

const legenda = String(b.legenda ?? r.legenda).replace(/\r/g, '').trim().slice(0, 2200) || r.legenda;
let quando = null;
if (acao === 'agendar') {
  const t = new Date(String(b.quando || '') + ':00-03:00');
  if (isNaN(t) || t.getTime() < Date.now() + 2 * 60000 || t.getTime() > Date.now() + 60 * 86400000) return nao('Escolha um horário entre 2 minutos e 60 dias a partir de agora.');
  quando = t.toISOString();
}
const novo = { ...r, legenda, atualizadoEm: new Date().toISOString(), erro: '' };
if (acao === 'agendar') Object.assign(novo, { status: 'agendado', quando });
if (acao === 'descartar') novo.status = 'descartado';
if (acao === 'cancelar') Object.assign(novo, { status: 'aguardando', quando: null });
return [{ json: { ok: true, acao, id: r.id, urls: r.urls, legenda, quando, rascunho_str: JSON.stringify(novo),
  mensagem: { agendar: 'Agendado! O fluxo publica sozinho no horário.', descartar: 'Carrossel descartado.', cancelar: 'Agendamento cancelado.', publicar: '' }[acao] } }];

// Junta o resultado da publicação com o rascunho e marca como publicado (ou erro)
const NO_ORIGEM = 'Valida ação';
const saida = [];
const origem = $(NO_ORIGEM).all();
const itens = $input.all();
for (let i = 0; i < itens.length; i++) {
  const o = origem[i] ? origem[i].json : origem[0].json;
  const r = JSON.parse(o.rascunho_str);
  const j = itens[i].json;
  if (j.error || !j.id) {
    const e = j.error;
    Object.assign(r, { status: 'erro', erro: 'O Instagram recusou: ' + String((e && (e.message || e.description)) || e || 'sem resposta').slice(0, 300) });
  } else {
    Object.assign(r, { status: 'publicado', media_id: j.id, permalink: j.permalink || '', publicadoEm: new Date().toISOString(), erro: '' });
  }
  r.atualizadoEm = new Date().toISOString();
  saida.push({ json: { id: r.id, ok: r.status === 'publicado', permalink: r.permalink || '', erro: r.erro || '', rascunho_str: JSON.stringify(r) } });
}
return saida;

// Lê a fila de agendamentos e devolve só o que já passou do horário
const fila = $input.first().json.fila || {};
const agora = Date.now();
return Object.entries(fila)
  .filter(([id, quando]) => /^car-[a-z0-9]+$/.test(id) && quando !== 'feito' && quando !== 'cancelado' && new Date(quando).getTime() <= agora)
  .map(([id]) => ({ json: { id } }));

// Só publica o que continua agendado (o dono pode ter cancelado ou publicado antes)
return $input.all().map(i => { try { return JSON.parse(i.json.rascunho || 'null'); } catch (e) { return null; } })
  .filter(r => r && r.status === 'agendado')
  .map(r => ({ json: { id: r.id, urls: r.urls, legenda: r.legenda, rascunho_str: JSON.stringify(r) } }));

// Junta o resultado da publicação com o rascunho e marca como publicado (ou erro)
const NO_ORIGEM = 'Prepara agendado';
const saida = [];
const origem = $(NO_ORIGEM).all();
const itens = $input.all();
for (let i = 0; i < itens.length; i++) {
  const o = origem[i] ? origem[i].json : origem[0].json;
  const r = JSON.parse(o.rascunho_str);
  const j = itens[i].json;
  if (j.error || !j.id) {
    const e = j.error;
    Object.assign(r, { status: 'erro', erro: 'O Instagram recusou: ' + String((e && (e.message || e.description)) || e || 'sem resposta').slice(0, 300) });
  } else {
    Object.assign(r, { status: 'publicado', media_id: j.id, permalink: j.permalink || '', publicadoEm: new Date().toISOString(), erro: '' });
  }
  r.atualizadoEm = new Date().toISOString();
  saida.push({ json: { id: r.id, ok: r.status === 'publicado', permalink: r.permalink || '', erro: r.erro || '', rascunho_str: JSON.stringify(r) } });
}
return saida;

const LIMITE_POR_HORA = 10;
const req = $('Novo carrossel (POST)').first().json;
const b = (req.body && typeof req.body === 'object') ? req.body : {};
const usos = Number(Object.values($input.first().json)[0]) || 0;
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const ESTILOS = ['escuro', 'claro', 'vibrante', 'natural', 'corporativo'];
